"""Загрузка и нормализация index.json (выход code-index, часть A).

Ожидаемая форма (допускаются синонимы ключей, см. _pick):
{
  "types": [{
     "full_name": "Ns.Outer.Inner", "name": "Inner", "kind": "class|struct|enum|interface",
     "namespace": "Ns", "file": "path/File.cs", "base": "Item", "interfaces": ["IFoo"],
     "parent": "Ns.Outer" | null,                      # вложенность
     "fields":  [{"name","type","default","mods":[..]}],
     "methods": [{"name","callees":["Foo.Bar","Baz"]}],
     "literals":[{"value":0.25,"member":"Start","raw":"0.25f"}],
     "refs": ["OtherType", ...]                       # необязательно: упомянутые типы
  }],
  "inheritance": {...}                                 # необязательно, пересчитывается
}
Поля fields/methods/literals могут лежать и на верхнем уровне списками с ключом "type".
Код только читает данные индекса; имена из референса остаются в рабочих файлах и в
публичные спеки не попадают (clean-room).
"""
from __future__ import annotations
import json
from collections import defaultdict
from pathlib import Path

GENERIC_NUM_SKIP = {0.0, 1.0, -1.0}


def _pick(d: dict, *keys, default=None):
    for k in keys:
        if k in d and d[k] is not None:
            return d[k]
    return default


class Type:
    __slots__ = ("full", "name", "kind", "ns", "file", "base", "interfaces", "parent",
                 "fields", "methods", "literals", "refs", "ancestors", "children_n")

    def __init__(self, d: dict):
        self.full = _pick(d, "full_name", "fullName", "fqn", "name")
        self.name = _pick(d, "name", "simple_name", default=self.full.split(".")[-1])
        self.kind = _pick(d, "kind", default="class")
        self.ns = _pick(d, "namespace", "ns", default="") or ""
        self.file = str(_pick(d, "file", "path", default="")).replace("\\", "/")
        b = _pick(d, "base", "base_type", "baseType", "extends")
        if isinstance(b, list):
            b = b[0] if b else None
        self.base = (b or None)
        self.interfaces = list(_pick(d, "interfaces", "implements", default=[]) or [])
        self.parent = _pick(d, "parent", "nesting_parent", "nestingParent", "declaring_type")
        self.fields = list(_pick(d, "fields", default=[]) or [])
        self.methods = list(_pick(d, "methods", default=[]) or [])
        self.literals = list(_pick(d, "literals", default=[]) or [])
        self.refs = set(_pick(d, "refs", "references", default=[]) or [])
        self.ancestors: list[str] = []      # простые имена предков, ближайший первым
        self.children_n = 0

    def simple(self, n: str | None) -> str | None:
        return n.split(".")[-1].split("<")[0] if n else n


class Index:
    def __init__(self, data: dict):
        self.raw_meta = {k: v for k, v in data.items() if k not in ("types", "fields", "methods", "literals")}
        self.types: list[Type] = [Type(t) for t in data.get("types", [])]
        by_full = {t.full: t for t in self.types}
        # верхнеуровневые списки -> в типы
        for key, attr in (("fields", "fields"), ("methods", "methods"), ("literals", "literals")):
            for it in data.get(key, []) or []:
                owner = _pick(it, "type", "owner", "declaring_type")
                t = by_full.get(owner)
                if t is not None:
                    getattr(t, attr).append(it)
        self.by_full = by_full
        self.by_name: dict[str, list[Type]] = defaultdict(list)
        for t in self.types:
            self.by_name[t.name].append(t)
        self._resolve()

    def lookup(self, name: str | None, ctx: Type | None = None) -> Type | None:
        if not name:
            return None
        if name in self.by_full:
            return self.by_full[name]
        s = name.split(".")[-1].split("<")[0]
        c = self.by_name.get(s)
        if not c:
            return None
        if ctx is not None:  # предпочесть тот же namespace
            for t in c:
                if t.ns == ctx.ns:
                    return t
        return c[0]

    def _resolve(self) -> None:
        for t in self.types:
            seen, chain, cur = {t.full}, [], t
            while cur is not None and cur.base:
                bt = self.lookup(cur.base, cur)
                chain.append(cur.simple(cur.base))
                if bt is None or bt.full in seen:
                    break
                seen.add(bt.full)
                cur = bt
            t.ancestors = chain
        # refs из вызовов, если индекс их не дал
        names = set(self.by_name)
        for t in self.types:
            if t.refs:
                continue
            r = set()
            for m in t.methods:
                for c in _pick(m, "callees", "calls", default=[]) or []:
                    parts = str(c).replace("::", ".").split(".")
                    for p in parts[:-1] + parts[-1:]:
                        p = p.split("<")[0]
                        if p in names:
                            r.add(p)
            for f in t.fields:
                ft = str(_pick(f, "type", default="")).replace("[]", "")
                ft = ft.split("<")[-1].rstrip(">").split(".")[-1]
                if ft in names:
                    r.add(ft)
            t.refs = r
        for t in self.types:
            t.refs.discard(t.name)

    def chain(self, t: Type) -> list[Type | None]:
        """Предки как объекты Type (None, если тип внешний)."""
        out, cur, seen = [], t, {t.full}
        while cur is not None and cur.base:
            bt = self.lookup(cur.base, cur)
            out.append(bt if bt and bt.full not in seen else None)
            if bt is None or bt.full in seen:
                break
            seen.add(bt.full)
            cur = bt
        return out

    def enclosing(self, t: Type) -> list[Type]:
        out, cur, seen = [], t, {t.full}
        while cur is not None and cur.parent:
            p = self.by_full.get(cur.parent) or self.lookup(cur.parent, cur)
            if p is None or p.full in seen:
                break
            seen.add(p.full)
            out.append(p)
            cur = p
        return out


def load_index(path: str | Path) -> Index:
    data = json.loads(Path(path).read_text(encoding="utf-8"))
    return Index(data)
