"""Запасной индекс C# для тестов, пока нет настоящего index.json (часть A).

Регулярки + скобочный разбор, не Roslyn: типы (в т.ч. вложенные), базы, поля с
инициализаторами, методы с вызовами, числовые литералы. Форма — как в index_io.py.

  python fallback_index.py --src "C:/visual projects/wol-ref/src" --out index.json
"""
from __future__ import annotations
import argparse, json, re, sys
from pathlib import Path

KW = {"if", "for", "while", "switch", "foreach", "return", "typeof", "nameof", "lock", "using",
      "catch", "sizeof", "default", "new", "fixed", "checked", "unchecked", "when", "await", "base_"}
TYPE_RE = re.compile(r"(?:^|[\s\]])(class|struct|enum|interface)\s+([A-Za-z_]\w*)\s*(<[^{;]*?>)?\s*(?::\s*([^{;]*?))?\s*(?:where\s[^{;]*)?$", re.S)
NUM_RE = re.compile(r"(?<![\w.])(\d+\.\d+|\d+|\.\d+)(?:[eE][-+]?\d+)?([fFdDmM]?)(?![\w])")
IDENT_RE = re.compile(r"[A-Za-z_]\w*")
CALL_RE = re.compile(r"((?:[A-Za-z_]\w*\s*\.\s*)*[A-Za-z_]\w*)\s*(?:<[^<>()]*>)?\s*\(")
MODS = {"public", "private", "protected", "internal", "static", "const", "readonly", "virtual",
        "override", "abstract", "sealed", "new", "extern", "unsafe", "partial", "async", "volatile", "event"}


def clean(src: str) -> str:
    """Убрать комментарии и строки/символы, сохранив длину и переводы строк."""
    out, i, n = [], 0, len(src)
    while i < n:
        c = src[i]
        two = src[i:i + 2]
        if two == "//":
            j = src.find("\n", i)
            j = n if j < 0 else j
            out.append(" " * (j - i)); i = j
        elif two == "/*":
            j = src.find("*/", i + 2)
            j = n if j < 0 else j + 2
            out.append(re.sub(r"[^\n]", " ", src[i:j])); i = j
        elif c == '"' or (c == "@" and src[i + 1:i + 2] == '"') or (c == "$" and src[i + 1:i + 3] in ('"', '@"')):
            verbatim = "@" in src[i:i + 3].split('"')[0]
            j = src.find('"', i) + 1
            while j < n:
                if verbatim:
                    if src[j] == '"':
                        if src[j + 1:j + 2] == '"':
                            j += 2; continue
                        break
                else:
                    if src[j] == "\\":
                        j += 2; continue
                    if src[j] == '"':
                        break
                j += 1
            j = min(j + 1, n)
            out.append('""' + re.sub(r"[^\n]", " ", src[i + 2:j]) if j - i >= 2 else " "); i = j
        elif c == "'":
            j = i + 1
            while j < n and src[j] != "'":
                j += 2 if src[j] == "\\" else 1
            j = min(j + 1, n)
            out.append("' '" + " " * (j - i - 3) if j - i >= 3 else " " * (j - i)); i = j
        else:
            out.append(c); i += 1
    return "".join(out)


def match_braces(s: str) -> dict[int, int]:
    st, m = [], {}
    for i, c in enumerate(s):
        if c == "{":
            st.append(i)
        elif c == "}" and st:
            m[st.pop()] = i
    return m


def split_top(s: str, sep=",") -> list[str]:
    out, d, cur = [], 0, []
    for c in s:
        if c in "<([":
            d += 1
        elif c in ">)]":
            d -= 1
        if c == sep and d == 0:
            out.append("".join(cur).strip()); cur = []
        else:
            cur.append(c)
