      "catch", "sizeof", "default", "new", "fixed", "checked", "unchecked", "when", "await"}
TYPE_RE = re.compile(r"(?:^|[\s\]])(class|struct|enum|interface)\s+([A-Za-z_]\w*)\s*(<[^{;]*?>)?\s*"
