IDENT_RE = re.compile(r"[A-Za-z_]\w*")
CALL_RE = re.compile(r"((?:[A-Za-z_]\w*\s*\.\s*)*[A-Za-z_]\w*)\s*(?:<[^<>()]*>)?\s*\(")
MODS = {"public", "private", "protected", "internal", "static", "const", "readonly", "virtual",
        "override", "abstract", "sealed", "new", "extern", "unsafe", "partial", "async", "volatile", "event"}


def clean(src: str) -> str:
    """Убрать комментарии и содержимое строк/символов, сохранив длину и переводы строк."""
    out, i, n = [], 0, len(src)
    blank = lambda t: re.sub(r"[^\n]", " ", t)
    while i < n:
        c = src[i]
        two = src[i:i + 2]
        if two == "//":
            j = src.find("\n", i)
            j = n if j < 0 else j
            out.append(" " * (j - i)); i = j
        elif two == "/*":
            j = src.find("*/", i + 2)
            j = n if j < 0 else j + 2
            out.append(blank(src[i:j])); i = j
        elif c == '"' or (c in "@$" and src[i + 1:i + 2] == '"') or (c in "@$" and src[i + 1:i + 3] in ('$"', '@"')):
            q = src.find('"', i)
            verbatim = "@" in src[i:q]
            j = q + 1
            while j < n:
                if verbatim:
                    if src[j] == '"':
                        if src[j + 1:j + 2] == '"':
                            j += 2; continue
                        break
                else:
                    if src[j] == "\\":
                        j += 2; continue
                    if src[j] == '"':
                        break
                j += 1
            j = min(j + 1, n)
            out.append(blank(src[i:j])); i = j
        elif c == "'":
            j = i + 1
            while j < n and src[j] != "'":
                j += 2 if src[j] == "\\" else 1
            j = min(j + 1, n)
            out.append(" " * (j - i)); i = j
        else:
            out.append(c); i += 1
    return "".join(out)


def match_braces(s: str) -> dict[int, int]:
    st, m = [], {}
    for i, c in enumerate(s):
        if c == "{":
            st.append(i)
        elif c == "}" and st:
            m[st.pop()] = i
    return m


def split_top(s: str, sep=",") -> list[str]:
    out, d, cur = [], 0, []
    for c in s:
        if c in "<([":
            d += 1
        elif c in ">)]":
            d -= 1
        if c == sep and d == 0:
            out.append("".join(cur).strip()); cur = []
        else:
            cur.append(c)
    if "".join(cur).strip():
        out.append("".join(cur).strip())
    return out


def literals_of(text: str, member: str, base_off: int, line_of) -> list[dict]:
    res, seen = [], set()
    for m in NUM_RE.finditer(text):
        raw = m.group(0)
        try:
            v = float(re.sub(r"[fFdDmM]$", "", raw))
        except ValueError:
            continue
        if (member, v) in seen:
            continue
