def parse_file(path: Path, rel: str, types: list[dict]) -> None:
    raw = path.read_text(encoding="utf-8-sig", errors="replace")
    s = clean(raw)
    br = match_braces(s)
    nl = [i for i, c in enumerate(s) if c == "\n"]
    line_of = lambda off: bisect.bisect_right(nl, off) + 1
    dirns = rel.rsplit("/", 1)[0].replace("/", ".") if "/" in rel else ""

    def new_type(kind, name, ns, owner, line):
