            m = re.findall(r"([A-Za-z_]\w*)\s*(?:<[^>]*>)?\s*\(", decl)
            name = m[-1] if m else (decl.split()[-1] if decl.split() else "?")
            owner["methods"].append({"name": name, "callees": callees_of(expr), "line": line_of(a)})
            owner["literals"] += literals_of(expr, name, a + h.find("=>"), line_of)
            return
        decl = h if eq is None else h[:eq.start()]
        value = "" if eq is None else h[eq.end():]
        if "(" in decl and eq is None:                              # абстрактный/extern метод
            m = re.findall(r"([A-Za-z_]\w*)\s*(?:<[^>]*>)?\s*\(", decl)
            if m:
                owner["methods"].append({"name": m[0], "callees": [], "line": line_of(a), "abstract": True})
            return
        toks = [t for t in re.split(r"\s+", decl.strip()) if t]
        mods = [t for t in toks if t in MODS]
        rest = " ".join(t for t in toks if t not in MODS)
        if not rest:
            return
        parts = split_top(rest)
        mt = re.match(r"^(.*\S)\s+([A-Za-z_]\w*)$", parts[0])
        if not mt:
            return
        ftype = mt.group(1)
        names = [mt.group(2)] + [p for p in parts[1:] if re.fullmatch(r"[A-Za-z_]\w*", p)]
        for nm in names:
            owner["fields"].append({"name": nm, "type": ftype,
                                    "default": re.sub(r"\s+", " ", value).strip()[:80] or None,
                                    "mods": mods, "line": line_of(a)})
        if value:
            owner["_idents"].update(IDENT_RE.findall(value))
            owner["literals"] += literals_of(value, names[0], a + (eq.end() if eq else 0), line_of)

    def method_block(h, a, b_, owner):
        body = s[a:b_]
        owner["_idents"].update(IDENT_RE.findall(h + " " + body))
        p = h.find("(")
        if p >= 0:
            m = re.findall(r"([A-Za-z_]\w*)\s*(?:<[^>]*>)?\s*$", h[:p])
            name = m[-1] if m else "?"
        else:                                                       # свойство { get; set; }
            toks = h.split()
            name = toks[-1] if toks else "?"
            tt = [t for t in toks if t not in MODS]
            if len(tt) >= 2:
                owner["fields"].append({"name": tt[-1], "type": " ".join(tt[:-1]), "default": None,
                                        "mods": [t for t in toks if t in MODS] + ["property"], "line": line_of(a)})
            if not re.search(r"\b(get|set)\s*\{", body):
                return
        owner["methods"].append({"name": name, "callees": callees_of(body), "line": line_of(a)})
        owner["literals"] += literals_of(body, name, a, line_of)

    def scope(a, b, ns, owner):
        i, hs = a, a
        while i < b:
            c = s[i]
            if c == ";":
                if owner is not None:
                    member_stmt(s[hs:i], hs, owner)
                hs = i + 1
            elif c == "{":
                j = br.get(i, b)
                h = re.sub(r"\[[^\[\]]*\]", " ", s[hs:i]).strip()
                tm = TYPE_RE.search(h)
                if re.match(r"^namespace\s", h):
                    scope(i + 1, j, h.split(None, 1)[1].strip(), None)
                elif tm and not re.search(r"=>|(?<![=!<>])=(?!=)", h):
                    kind, name, _, bases = tm.groups()
                    td = new_type(kind, name, ns or dirns, owner, line_of(hs))
