                        for x in split_top(bases):
                            if base is None and kind == "class" and not re.match(r"I[A-Z]", x.split(".")[-1]):
                                base = x
                            else:
                                ifs.append(x)
                        td["base"], td["interfaces"] = base, ifs
                    types.append(td)
                    if kind == "enum":
                        td["members"] = [x.split("=")[0].strip() for x in split_top(s[i + 1:j]) if x.strip()]
                    else:
                        scope(i + 1, j, ns, td)
                elif owner is not None:
                    eq = re.search(r"(?<![=!<>])=(?![=>])", h)
                    if eq and "(" not in h[:eq.start()]:            # инициализатор поля { ... };
                        k = s.find(";", j)
                        k = b if k < 0 else k
                        member_stmt(s[hs:k], hs, owner)
                        i, hs = k + 1, k + 1
                        continue
                    method_block(h, i + 1, j, owner)
                i, hs = j + 1, j + 1
                continue
            i += 1

    scope(0, len(s), "", None)


def build(src: Path) -> dict:
    types: list[dict] = []
    files = sorted(src.rglob("*.cs"))
    for p in files:
        rel = p.relative_to(src).as_posix()
        try:
            parse_file(p, rel, types)
        except Exception as e:  # один плохой файл не роняет индекс
            print(f"[fallback_index] {rel}: {e!r}", file=sys.stderr)
    names = {t["name"] for t in types}
    for t in types:
        ids = t.pop("_idents")
        t["refs"] = sorted((ids & names) - {t["name"]})
    return {"schema": "reverse-kit-index/1", "generator": "fallback_index.py (regex)", "root": str(src),
            "files": len(files), "types": types}


def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--src", required=True)
    ap.add_argument("--out", required=True)
    a = ap.parse_args()
    d = build(Path(a.src))
    Path(a.out).parent.mkdir(parents=True, exist_ok=True)
    Path(a.out).write_text(json.dumps(d, ensure_ascii=False), encoding="utf-8")
    print(f"[fallback_index] {d['files']} файлов, {len(d['types'])} типов -> {a.out}")


if __name__ == "__main__":
    main()

