# Универсальная таксономия систем для action-roguelite / метроидвании (Unity/C# и похожие).
# Системы 00-30 повторяют нумерацию спеки WoL (игра №1), чтобы файлы спек и записи БД
# механик у разных игр совпадали по номеру. Корзина (bucket) — то, на что классифицируются
# типы; система (system) — в какой спек-файл корзина попадает. Корзины мельче систем.
#
# Правила (rules) — список; тип получает корзину правила с максимальным score.
# score = conf * затухание_по_глубине_наследования (для derives: 1 - 0.05*(глубина-1), не ниже 0.75).
# Условия внутри правила объединяются по И:
#   derives:       [глоб]  любой предок (по простому имени, без дженерик-аргументов)
#   direct:        [глоб]  только непосредственная база
#   interface:     [глоб]  реализует интерфейс
#   ns:            [глоб]  namespace или каталог файла
#   name:          regex   простое имя типа (re.search)
#   path:          regex   путь файла
#   kind:          [class|struct|enum|interface]
#   nested_in:     [глоб]  простое имя любого внешнего типа
#   nested_derives:[глоб]  внешний тип наследует от ...
#   top_level:     bool
# Слабые правила (conf < thresholds.accept) не принимаются сразу: типы с ними идут дальше
# в наследование корзины от предка, вложенность и близость по графу вызовов.
# Переопределения под игру — overrides/<slug>.yaml (exact:, rules:, generic_bases:, eval_alias:).

version: 1
thresholds:
  accept: 0.5          # минимальный score правила, чтобы принять сразу
  inherit_decay: 0.85  # уверенность корзины, унаследованной от предка/внешнего типа
  proximity_min_weight: 0.8
  proximity_min_share: 0.5
  proximity_ignore: [engine, lib, debug, unassigned, stats]   # хабы графа не голосуют

# предки, по которым корзину НЕ наследуем (слишком общие базы проекта)
generic_bases: [Entity, ComponentBase, State, StateMachine, MonoBehaviour, Object, Component, Base, Manager, Controller, Behaviour, WeightedItem]

