  "16": {slug: outfits,           title: "Облики и экипировка"}
  "17": {slug: hub-services,      title: "Хаб и NPC-сервисы"}
  "18": {slug: special-rooms,     title: "Особые комнаты"}
  "19": {slug: boss-rush,         title: "Режим гонки боссов"}
  "20": {slug: props-hazards,     title: "Пропы, ловушки, разрушаемые"}
  "21": {slug: summons,           title: "Призванные: миньоны, фамильяры, клоны"}
  "22": {slug: status-debuffs,    title: "Дебаффы и DoT"}
