  stats:        {system: "14", title: "Статы и модификаторы"}
  player:       {system: "01", title: "Игрок"}
  combat:       {system: "02", title: "Бой / здоровье / хитбоксы"}
  juice:        {system: "03", title: "Сочность / эффекты"}
  status:       {system: "04", title: "Статусы / DoT"}
  ability_core: {system: "05", title: "Способности: ядро и UI слотов"}
  ability_fx:   {system: "05", title: "Способности: касты, снаряды, зоны"}
  enemy:        {system: "06", title: "Враги"}
  enemy_atk:    {system: "06", title: "Атаки врагов"}
  levelgen:     {system: "07", title: "Генерация уровней"}
  decor:        {system: "07", title: "Декор / декораторы"}
  encounter:    {system: "08", title: "Энкаунтеры"}
