  summons:      {system: "21", title: "Призванные"}
  camera:       {system: "23", title: "Камера"}
  audio:        {system: "24", title: "Аудио"}
  ui:           {system: "25", title: "UI / HUD"}
  input:        {system: "26", title: "Ввод и настройки"}
  dialog_loc:   {system: "27", title: "Диалоги / локализация"}
  achv:         {system: "28", title: "Достижения"}
  flow_ui:      {system: "29", title: "Титул / загрузка / титры"}
  tutorial:     {system: "29", title: "Обучение"}
  lib:          {system: "--", title: "Сторонние библиотеки"}
  debug:        {system: "--", title: "Отладка и тесты"}
  art:          {system: "--", title: "Арт-утилиты"}
  unassigned:   {system: "--", title: "Не распознано"}

rules:
  # --- библиотеки / отладка: первыми и уверенно ---------------------------------------
  - {bucket: lib,   conf: 0.95, ns: ["Rewired*", "Properties", "UnityEngine*", "System*", "Steamworks*", "TMPro*", "DG.Tweening*", "*Extensions", "*Extension"]}
  - {bucket: lib,   conf: 0.9,  path: '(^|/)(Rewired|Plugins|ThirdParty|Third Party|Packages)[^/]*/'}
  - {bucket: lib,   conf: 0.85, path: '(^|/)AssemblyInfo\.'}
  - {bucket: debug, conf: 0.9,  name: '(Test|Tester|Debug\w*|Cheat\w*)$'}
  - {bucket: debug, conf: 0.85, derives: ["*Test", "*Tester"]}
  - {bucket: debug, conf: 0.8,  name: '^(Debug|Test)'}

  # --- наследование: самые надёжные сигналы -------------------------------------------
  - {bucket: items,    conf: 0.95, derives: [Item, Relic, Artifact, Perk, Trinket, Passive*]}
  - {bucket: decor,    conf: 0.9,  derives: [Decoration, Decorator, Doodad]}
  - {bucket: enemy,    conf: 0.95, derives: [Enemy, Monster, Mob, Hostile*, MiniBoss]}
  - {bucket: boss,     conf: 0.95, derives: [Boss]}
  - {bucket: hub_npc,  conf: 0.93, derives: [Npc, NPC, Vendor, Merchant, Shopkeeper]}
  - {bucket: props,    conf: 0.92, derives: [Destructible, Breakable, Hazard, Trap, Door, Interactable, Prop]}
  - {bucket: status,   conf: 0.93, derives: ["*DoTEffect", "*DotEffect", BaseEffect, StatusEffect, Buff, Debuff, Ailment]}
  - {bucket: loot,     conf: 0.9,  derives: [PickupItem, StoreItem, Pickup, Currency, Drop*, Wallet]}
  - {bucket: juice,    conf: 0.88, derives: [ParticleEffect, ParticleSystem*, *Emitter, ScreenShake*, VFX*, Fx, Effect]}
  - {bucket: summons,  conf: 0.88, derives: [Minion, BasicMinion, Familiar, *Familiar, Summon, *Summon, *Clone, Seeker]}
  - {bucket: levelgen, conf: 0.9,  derives: [TileSet, *TileSet, TileGrid*, Tilemap*, RoomGenerator, Generator]}
  - {bucket: run,      conf: 0.88, derives: [RunMod, Checkpoint*, Portal, ExitPortal]}
  - {bucket: ui,       conf: 0.85, derives: [*UI, *Ui, HudElement, MiniUIBar, Widget, Menu, Panel]}
  - {bucket: ability_fx, conf: 0.55, derives: [Projectile, Wave, ThrownItem, MeleeAttackObject, Beam, Bullet, *Burst, *Explosion]}   # слабо: общие базы атак
  # вложенные состояния игрока
  - {bucket: ability_fx, conf: 0.93, nested_in: [Player], derives: [SkillState, AbilityState, SpellState, Skill*State]}
  - {bucket: player,     conf: 0.88, nested_in: [Player]}
  - {bucket: enemy,      conf: 0.85, nested_in: [Enemy, Boss, MiniBoss], derives: [State]}
  - {bucket: enemy,      conf: 0.75, nested_in: [Enemy]}
  - {bucket: boss,       conf: 0.8,  nested_in: [Boss]}

  # --- интерфейсы / namespace ----------------------------------------------------------
  - {bucket: ui,       conf: 0.7, ns: ["*.UI", "UI", "*.Hud", "Hud"]}
  - {bucket: audio,    conf: 0.7, ns: ["*.Audio", "Audio", "*.Sound"]}
  - {bucket: input,    conf: 0.7, ns: ["*.Input", "Input"]}

  # --- имя / путь ---------------------------------------------------------------------
  - {bucket: meta,       conf: 0.85, name: '(SaveData|GameData|PlayerData|Profile|SaveManager|Unlock\w*|RunHistory\w*|Loadout\w*|Persistent\w*)$'}
  - {bucket: input,      conf: 0.8,  name: '(Input\w*|Controller(Layout|Platform|Map)\w*|Keybind\w*|GameSettings|Settings\w*|Cursor)$'}
  - {bucket: audio,      conf: 0.85, name: '(Sound|Audio|Bgm|Music|Sfx)\w*'}
  - {bucket: camera,     conf: 0.85, name: '(Camera|Cinemachine)\w*'}
  - {bucket: dialog_loc, conf: 0.85, name: '(Dialog|Dialogue|Localiz|Lang|Subtitle|Speaker)\w*'}
  - {bucket: achv,       conf: 0.85, name: '(Achievement|Steam\w*Manager|Trophy)\w*'}
  - {bucket: flow_ui,    conf: 0.8,  name: '^(Title\w*|Credits|Epilogue|Loading\w*|InitialLoad|Splash\w*|MainMenu)'}
  - {bucket: tutorial,   conf: 0.8,  name: '(Tutorial|Museum|Mirror)\w*'}
  - {bucket: outfits,    conf: 0.85, name: '^(Outfit|Headgear|Costume|Skin|Cosmetic)\w*'}
  - {bucket: coop,       conf: 0.8,  name: '(Pvp|Coop|Multiplayer|Lobby)\w*'}
  - {bucket: stats,      conf: 0.8,  name: '(StatMod|StatManager|StatData|VarStat|NumVarStat|Modifier(Type)?$|StatType)'}
  - {bucket: encounter,  conf: 0.8,  name: '(Encounter|EnemyFactory|EnemyDecorator|SpawnBudget|WaveSpawner|EnemySpawn\w*|HazardRoom|Survival)\w*'}
  - {bucket: levelgen,   conf: 0.75, name: '(TileSet|AutoTil|TileGrid|BoolGrid|Room(Gen|Layout|Template)\w*|Level(Gen|Builder)\w*|Dungeon\w*|Floor(Gen|Plan)\w*|Connector|Pathfind\w*|Grid\w*)'}
  - {bucket: decor,      conf: 0.8,  name: '(Deco|Decorator|Doodad)$'}
  - {bucket: juice,      conf: 0.7,  name: '(Effect|Emitter|Particle|Flash|Shake|Trail|Smoke|Sparkle|DamageText|DamageNumber|Debris|Confetti|Splash)\w*$'}
  - {bucket: status,     conf: 0.72, name: '(Burn|Freeze|Frozen|Poison|Shock|Slow|Root|Stun|Bleed|Curse|Mark)\w*(Effect|Status|Debuff)?$'}
  - {bucket: items,      conf: 0.72, name: '(Item|Relic|Perk|Trinket)$'}
  - {bucket: loot,       conf: 0.75, name: '(Gold|Coin|Wallet|Currency|DropTable|Loot|Store|Shop|Chest|Pickup|Price)\w*'}
  - {bucket: hub_npc,    conf: 0.8,  name: 'Npc$|^Npc'}
  - {bucket: summons,    conf: 0.7,  name: '(Minion|Familiar|Summon|Clone|Phantom|Spawn(ed)?Ally)\w*'}
  - {bucket: boss,       conf: 0.8,  name: 'Boss'}
  - {bucket: enemy,      conf: 0.6,  name: '^Enemy'}
  - {bucket: ui,         conf: 0.75, name: '(UI|Hud|HUD|Menu|Button|Tooltip|Compass|Indicator|Cursor|Panel|Bar)(\w{0,12})$'}
  - {bucket: props,      conf: 0.7,  name: '(Destructible|Hazard|Trap|Barricade|Door|Torch|Lever|Switch|Spike|Gate|Boulder|Pot|Crate|Barrel)\w*'}
  - {bucket: run,        conf: 0.65, name: '(Run|Stage|Floor|Portal|Checkpoint|Ending|Victory|GameOver|Difficulty|BossRoom)\w*'}
  - {bucket: player,     conf: 0.7,  name: '^(Player|Movement|Dash|Fall|Jump)\w*'}
  - {bucket: combat,     conf: 0.72, name: '^(Attack|Health|Hurtbox|Hitbox|Damage|Knockback|Stun|Melee|Parry|Block)\w*'}
  - {bucket: ability_core, conf: 0.7, name: '^(Arcana|Ability|Skill|Spell|Cooldown|Cast|Slot|Ult)\w*'}
  - {bucket: art,        conf: 0.7,  name: '(Palett|Palette|Recolor|SpriteSwap|DecorationApplier)\w*'}
  - {bucket: engine,     conf: 0.6,  name: '(Pool|Stopwatch|Timer|Anim\w*|Fsm|StateMachine|Singleton|Manager|Bundle|Rng|Random|Weighted\w*|Mask|Layer|Util\w*|Helper|Extension\w*)$'}
  - {bucket: engine,     conf: 0.55, kind: [enum, interface], top_level: true}

