toolu_017jj7sqQ3hx2v2p7YWyzamq.content:
"""C1: автоматическое отнесение каждого типа к системной корзине.

  python auto_coverage.py --index index.json --taxonomy taxonomy.yaml --out DIR
         [--override overrides/wol.yaml ...] [--hand hand_coverage.csv]

Слои (по убыванию надёжности):
  1. exact-переопределения игры (conf 1.0);
  2. правила таксономии: наследование (в т.ч. вложенные состояния), интерфейсы, namespace,
     путь/имя файла — побеждает правило с максимальным score;
  3. наследование корзины от ближайшего «своего» предка (не из generic_bases);
  4. корзина внешнего (вложенного-в) типа;
  5. близость по графу вызовов/ссылок: голосование уже размеченных соседей (с IDF-гашением хабов);
  остальное -> unassigned.
Выход: coverage.csv (type, base, bucket, confidence, reason, system, file, kind, parent),
coverage.md (сводка), и, если дан --hand, строка согласия в coverage.md + agreement.json.
"""
from __future__ import annotations
import argparse, csv, fnmatch, json, math, re, sys
from collections import Counter, defaultdict
from pathlib import Path

import yaml

sys.path.insert(0, str(Path(__file__).parent))
from index_io import Index, Type, load_index  # noqa: E402


def load_taxonomy(path: str, overrides: list[str]) -> dict:
    tax = yaml.safe_load(Path(path).read_text(encoding="utf-8"))
    tax.setdefault("exact", {})
    tax.setdefault("eval_alias", {})
    for o in overrides or []:
        ov = yaml.safe_load(Path(o).read_text(encoding="utf-8")) or {}
        tax["exact"].update(ov.get("exact", {}))
        tax["eval_alias"].update(ov.get("eval_alias", {}))
        # правила игры идут впереди (при равном score побеждает первое)
        tax["rules"] = list(ov.get("rules", [])) + tax["rules"]
        tax["generic_bases"] = list(tax.get("generic_bases", [])) + list(ov.get("generic_bases", []))
        for k, v in (ov.get("buckets") or {}).items():
            tax["buckets"][k] = v
        for k, v in (ov.get("systems") or {}).items():
            tax["systems"][str(k)] = v
        if ov.get("thresholds"):
            tax["thresholds"].update(ov["thresholds"])
        tax.setdefault("overrides_used", []).append(str(o))
    return tax


def _g(pats, s: str) -> bool:
    return any(fnmatch.fnmatchcase(s, p) for p in pats)


class Rule:
    def __init__(self, r: dict, i: int):
        self.r, self.i = r, i
        self.bucket, self.conf = r["bucket"], float(r.get("conf", 0.7))
        self.name = re.compile(r["name"]) if r.get("name") else None
        self.path = re.compile(r["path"]) if r.get("path") else None

    def match(self, t: Type, idx: Index, encl: list[Type]) -> tuple[float, str] | None:
        r = self.r
        score_mul, why = 1.0, []
        if "kind" in r and t.kind not in r["kind"]:
            return None
        if r.get("top_level") and t.parent:
            return None
        if self.name is not None:
            if not self.name.search(t.name):
                return None
            why.append(f"name~{self.r['name'][:28]}")
        if self.path is not None:
            if not self.path.search(t.file):
                return None
            why.append("path")
        if "ns" in r:
            cand = [t.ns, t.file.rsplit("/", 1)[0].replace("/", ".") if "/" in t.file else ""]
            if not any(c and _g(r["ns"], c) for c in cand):
                return None
            why.append("ns")
        if "interface" in r:
            hit = [i for i in t.interfaces if _g(r["interface"], i.split(".")[-1].split("<")[0])]
            if not hit:
                return None
            why.append(f"iface {hit[0]}")
        if "direct" in r:
            if not (t.base and _g(r["direct"], t.simple(t.base))):
                return None
            why.append(f"base {t.simple(t.base)}")
        if "derives" in r:
            names = [t.simple(t.base)] if False else t.ancestors
            hit = next(((d, a) for d, a in enumerate(names, 1) if _g(r["derives"], a)), None)
            if hit is None:
                return None
            score_mul *= max(0.75, 1 - 0.05 * (hit[0] - 1))
            why.append(f"derives {hit[1]}" + (f" (d{hit[0]})" if hit[0] > 1 else ""))
        if "nested_in" in r:
            h = next((e for e in encl if _g(r["nested_in"], e.name)), None)
            if h is None:
                return None
            why.append(f"nested in {h.name}")
        if "nested_derives" in r:
            if not any(_g(r["nested_derives"], a) for e in encl for a in e.ancestors):
                return None
            why.append("nested in derived")
        if not why and not any(k in r for k in ("kind", "top_level")):
            return None
        if "kind" in r and not why:
            why.append(f"kind {t.kind}")
        return self.conf * score_mul, "; ".join(why)


def classify(idx: Index, tax: dict) -> dict[str, dict]:
    th = tax["thresholds"]
    accept = th["accept"]
    rules = [Rule(r, i) for i, r in enumerate(tax["rules"])]
    generic = set(tax.get("generic_bases", []))
    exact = tax.get("exact", {})
    ignore_prox = set(th.get("proximity_ignore", []))
    res: dict[str, dict] = {}
    weak: dict[str, tuple] = {}

    def encl_of(t):
        return idx.enclosing(t)

    # --- слой 1-2: exact + правила
    for t in idx.types:
        hit = None
        for key in (t.full, t.name):
            for pat, b in exact.items():
                if fnmatch.fnmatchcase(key, pat):
                    hit = (b, 1.0, f"override {pat}")
                    break
            if hit:
                break
        if hit is None:
            enc = encl_of(t)
            best = None
            for rl in rules:
                m = rl.match(t, idx, enc)
                if m and (best is None or m[0] > best[0]):
                    best = (m[0], rl.bucket, m[1])
            if best:
                if best[0] >= accept:
                    hit = (best[1], round(best[0], 3), "rule: " + best[2])
                else:
                    weak[t.full] = (best[1], round(best[0], 3), "weak rule: " + best[2])
        if hit:
            res[t.full] = {"bucket": hit[0], "conf": hit[1], "reason": hit[2]}

    # --- слой 3-4: наследование корзины и вложенность
    def inherit(t, depth=0):
        for anc in idx.chain(t):
            if anc is None:
                break
            if anc.name in generic:
                continue
            r = res.get(anc.full)
            if r and r["conf"] >= accept and r["bucket"] not in ("unassigned",):
                return {"bucket": r["bucket"], "conf": round(r["conf"] * th["inherit_decay"], 3),
                        "reason": f"inherits bucket of {anc.name}"}
        for e in idx.enclosing(t):
            r = res.get(e.full)
            if r and r["conf"] >= accept and e.name not in generic:
                return {"bucket": r["bucket"], "conf": round(r["conf"] * th["inherit_decay"] * 0.9, 3),
                        "reason": f"nested in {e.name}"}
        return None

    # несколько проходов: предки уже могут быть разрешены в предыдущем
    for _ in range(4):
        changed = False
        for t in idx.types:
            if t.full in res:
                continue
            r = inherit(t)
            if r:
                res[t.full] = r
                changed = True
        if not changed:
            break

    # --- слой 5: близость по графу
    indeg = Counter()
    for t in idx.types:
        for r_ in t.refs:
            indeg[r_] += 1
    incoming: dict[str, list[str]] = defaultdict(list)
    for t in idx.types:
        for r_ in t.refs:
            incoming[r_].append(t.name)
    by_name = {}
    for t in idx.types:
        by_name.setdefault(t.name, t)

    def vote(t):
        v, n = Counter(), 0
        for nb, w0 in [(x, 1.0) for x in t.refs] + [(x, 0.8) for x in incoming.get(t.name, [])]:
            o = by_name.get(nb)
            if o is None or o.full == t.full:
                continue
            r = res.get(o.full)
            if not r or r["conf"] < accept or r["bucket"] in ignore_prox:
                continue
            w = w0 * r["conf"] / math.log(2 + indeg[nb])
            v[r["bucket"]] += w
            n += 1
        return v, n

    for sweep in range(2):
        new = {}
        for t in idx.types:
            if t.full in res and not (sweep == 0 and False):
                continue
            v, n = vote(t)
            tot = sum(v.values())
            if tot >= th["proximity_min_weight"]:
                b, top = v.most_common(1)[0]
                share = top / tot
                if share >= th["proximity_min_share"]:
                    new[t.full] = {"bucket": b, "conf": round(min(0.62, 0.3 + 0.3 * share + 0.03 * min(n, 4)), 3),
                                   "reason": f"call-graph proximity ({n} neighbors, share {share:.2f})"}
        if not new:
            break
        # результаты близости голосуют только со следующего прохода и только если conf>=accept
        res.update(new)

    # --- остаток: слабое правило как есть, иначе unassigned
    for t in idx.types:
        if t.full not in res:
            if t.full in weak:
                b, c, why = weak[t.full]
                res[t.full] = {"bucket": b, "conf": c, "reason": why}
            else:
                res[t.full] = {"bucket": "unassigned", "conf": 0.0, "reason": "no rule matched"}
    return res


def write_outputs(idx: Index, tax: dict, res: dict, out: Path, hand: Path | None, hand_alias: dict | None):
    out.mkdir(parents=True, exist_ok=True)
    systems = tax["systems"]
    bsys = lambda b: tax["buckets"].get(b, {}).get("system", "--")
    rows = []
    for t in idx.types:
        r = res[t.full]
        rows.append({"type": t.full, "base": t.base or f"({t.kind})", "bucket": r["bucket"],
                     "confidence": f"{r['conf']:.2f}", "reason": r["reason"], "system": bsys(r["bucket"]),
                     "file": t.file, "kind": t.kind, "parent": t.parent or ""})
    with (out / "coverage.csv").open("w", encoding="utf-8", newline="") as f:
        w = csv.DictWriter(f, fieldnames=list(rows[0].keys()))
        w.writeheader()
        w.writerows(rows)

    n = len(rows)
    cb = Counter(r["bucket"] for r in rows)
    cs = Counter(r["system"] for r in rows)
    hi = sum(1 for r in rows if float(r["confidence"]) >= 0.8)
    mid = sum(1 for r in rows if 0.5 <= float(r["confidence"]) < 0.8)
    lo = sum(1 for r in rows if 0 < float(r["confidence"]) < 0.5)
    un = cb.get("unassigned", 0)
    meth = Counter(re.split(r"[:( ]", r["reason"])[0] + (":" + r["reason"].split()[1] if r["reason"].startswith(("rule", "weak")) and False else "")
                   for r in rows)
    md = [f"# Авто-покрытие: {n} типов", "",
          f"Таксономия: `{tax.get('overrides_used') or 'generic'}`. Не распознано: **{un}** ({un * 100 / n:.1f}%).",
          f"Уверенность: высокая (>=0.8) {hi} ({hi * 100 / n:.0f}%), средняя (0.5-0.8) {mid}, низкая (<0.5) {lo}, нет {un}.", ""]
    ag = None
    if hand:
        ag = evaluate(rows, hand, hand_alias or tax.get("eval_alias", {}))
        md += ["## Согласие с ручной разметкой", "", ag["md"], ""]
        (out / "agreement.json").write_text(json.dumps({k: v for k, v in ag.items() if k != "md"},
                                                       ensure_ascii=False, indent=1), encoding="utf-8")
    md += ["## По системам", "", "| Система | Типов | Корзины |", "|---|---|---|"]
    for sid in sorted(cs):
        bs = ", ".join(f"{b}:{c}" for b, c in cb.most_common() if bsys(b) == sid)
        md.append(f"| {sid} {systems.get(sid, {}).get('slug', '?')} | {cs[sid]} | {bs} |")
    md += ["", "## По способу отнесения", "", "| Способ | Типов |", "|---|---|"]
    for k, c in Counter(("override" if r["reason"].startswith("override") else
                         "rule" if r["reason"].startswith("rule") else
                         "inherit" if r["reason"].startswith(("inherits", "nested in")) else
                         "proximity" if r["reason"].startswith("call-graph") else
                         "weak rule" if r["reason"].startswith("weak") else "none") for r in rows).most_common():
        md.append(f"| {k} | {c} |")
    low = sorted((r for r in rows if float(r["confidence"]) < 0.6), key=lambda r: float(r["confidence"]))
    md += ["", f"## На ручной разбор (conf < 0.6): {len(low)}", "",
           "Первые 60 по возрастанию уверенности; полный список — coverage.csv.", "",
           "| Тип | База | Корзина | conf | Причина |", "|---|---|---|---|---|"]
    for r in low[:60]:
        md.append(f"| {r['type']} | {r['base']} | {r['bucket']} | {r['confidence']} | {r['reason']} |")
    (out / "coverage.md").write_text("\n".join(md) + "\n", encoding="utf-8")
    return ag


def evaluate(rows: list[dict], hand: Path, alias: dict) -> dict:
    """Сравнить с ручным coverage.csv (file, base_class, bucket, ...): на уровне файлов."""
    hrows = list(csv.DictReader(Path(hand).open(encoding="utf-8")))
    byfile: dict[str, list[dict]] = defaultdict(list)
    for r in rows:
        byfile[r["file"]].append(r)
    byname = defaultdict(list)
    for f, rs in byfile.items():
        byname[f.rsplit("/", 1)[-1]].append(f)
    tot = ok = missing = 0
    okc = totc = 0
    per = defaultdict(lambda: [0, 0])
    conf = Counter()
    wrong = []
    for h in hrows:
        hf = h["file"].replace("\\", "/")
        f = hf if hf in byfile else (byname[hf.rsplit("/", 1)[-1]][0] if byname.get(hf.rsplit("/", 1)[-1]) else None)
        if f is None:
            missing += 1
            continue
        rs = byfile[f]
        stem = f.rsplit("/", 1)[-1].rsplit(".", 1)[0]
        prim = next((r for r in rs if r["type"].split(".")[-1] == stem and not r["parent"]), None) \
            or next((r for r in rs if not r["parent"]), rs[0])
        hb = h["bucket"]
        accept = {hb} | {a for a, b in alias.items() if b == hb or a == hb} if False else None
        ok_set = {hb}
        for k, v in alias.items():             # alias: наша_корзина -> ручная корзина
            if v == hb:
                ok_set.add(k)
        good = prim["bucket"] in ok_set
        tot += 1
        ok += good
        per[hb][0] += 1
        per[hb][1] += good
        if float(prim["confidence"]) >= 0.8:
            totc += 1
            okc += good
        if not good:
            conf[(hb, prim["bucket"])] += 1
            wrong.append((f, hb, prim["bucket"], prim["confidence"]))
    pct = 100 * ok / max(tot, 1)
    lines = [f"Сопоставлено файлов: **{tot}** (нет в индексе: {missing}). "
             f"Согласие по корзине: **{pct:.1f}%** ({ok}/{tot}).",
             f"Среди уверенных (conf >= 0.8): {100 * okc / max(totc, 1):.1f}% ({okc}/{totc}); "
             f"охват уверенными {100 * totc / max(tot, 1):.0f}%.", "",
             "| Ручная корзина | Файлов | Согласие |", "|---|---|---|"]
    for b, (n_, g) in sorted(per.items(), key=lambda kv: -kv[1][0]):
        lines.append(f"| {b} | {n_} | {100 * g / n_:.0f}% ({g}) |")
    lines += ["", "Частые расхождения (ручная -> авто):", ""]
    for (a, b), c in conf.most_common(12):
        lines.append(f"- {a} -> {b}: {c}")
    return {"md": "\n".join(lines), "agreement_pct": round(pct, 2), "files": tot, "agree": ok,
            "confident_agreement_pct": round(100 * okc / max(totc, 1), 2), "confident_files": totc,
            "missing": missing, "wrong_sample": wrong[:200]}


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--index", required=True)
    ap.add_argument("--taxonomy", required=True)
    ap.add_argument("--out", required=True)
    ap.add_argument("--override", action="append", default=[], help="overrides/<game>.yaml (можно несколько)")
    ap.add_argument("--hand", help="ручной coverage.csv (file,base_class,bucket,...) для оценки согласия")
    a = ap.parse_args()
    idx = load_index(a.index)
    tax = load_taxonomy(a.taxonomy, a.override)
    res = classify(idx, tax)
    ag = write_outputs(idx, tax, res, Path(a.out), Path(a.hand) if a.hand else None, None)
    cb = Counter(r["bucket"] for r in res.values())
    print(f"[auto_coverage] {len(res)} типов; unassigned {cb.get('unassigned', 0)}; -> {a.out}/coverage.csv")
    if ag:
        print(f"[auto_coverage] согласие с ручной разметкой: {ag['agreement_pct']}% "
              f"({ag['agree']}/{ag['files']}); среди conf>=0.8: {ag['confident_agreement_pct']}%")


if __name__ == "__main__":
    main()

