"""Общее для records/: загрузка, схема, склейка файлов одной системы, поиск TODO.

  python recio.py FILE_OR_DIR [...]      # валидация (схема + семантика), код 1 при ошибках
  python recio.py DIR --strict           # TODO в rules/catalog/goal тоже ошибка
"""
from __future__ import annotations
import argparse, re, sys
from pathlib import Path

import yaml

HERE = Path(__file__).parent
SCHEMA_PATH = HERE / "schema.yaml"
TODO_RE = re.compile(r"^\s*TODO\b|\bTODO:", re.I)


def load_schema() -> dict:
    return yaml.safe_load(SCHEMA_PATH.read_text(encoding="utf-8"))


def is_todo(s) -> bool:
    return isinstance(s, str) and (not s.strip() or bool(TODO_RE.search(s)))


def find_files(paths) -> list[Path]:
    out: list[Path] = []
    for p in paths:
        p = Path(p)
        if p.is_dir():
            out += sorted(x for x in p.glob("*.y*ml") if x.suffix in (".yaml", ".yml"))
        elif p.exists():
            out.append(p)
        else:
            raise FileNotFoundError(p)
    return out


def load_file(p: Path) -> dict:
    d = yaml.safe_load(p.read_text(encoding="utf-8")) or {}
    d["_path"] = str(p)
    return d


def validate_schema(d: dict) -> list[str]:
    try:
        import jsonschema
    except ImportError:
        return _mini_validate(d)
    v = jsonschema.Draft202012Validator(load_schema())
    errs = []
    for e in sorted(v.iter_errors({k: x for k, x in d.items() if k != "_path"}), key=lambda e: list(e.path)):
        loc = "/".join(str(x) for x in e.path) or "(root)"
        errs.append(f"{loc}: {e.message[:200]}")
    return errs


def _mini_validate(d: dict) -> list[str]:  # без jsonschema: только обязательное
    errs = []
    for k in ("schema", "game", "system"):
        if k not in d:
            errs.append(f"(root): нет поля {k}")
    for i, r in enumerate(d.get("rules", []) or []):
        for k in ("id", "title", "behavior"):
            if k not in r:
                errs.append(f"rules/{i}: нет {k}")
    for i, r in enumerate(d.get("catalog", []) or []):
        for k in ("id", "kind", "own_name"):
            if k not in r:
                errs.append(f"catalog/{i}: нет {k}")
    return errs


def validate_semantics(d: dict, strict: bool = False) -> list[str]:
    errs, seen = [], set()
    for sec in ("rules", "catalog"):
        for r in d.get(sec, []) or []:
            if r.get("id") in seen:
                errs.append(f"{sec}: дубликат id {r.get('id')}")
            seen.add(r.get("id"))
    if strict:
        if is_todo(d.get("goal", "")):
            errs.append("goal: TODO")
        for r in d.get("rules", []) or []:
            if is_todo(r.get("behavior")):
                errs.append(f"rule {r.get('id')}: behavior TODO")
            if not r.get("source_refs"):
                errs.append(f"rule {r.get('id')}: нет source_refs")
        for r in d.get("catalog", []) or []:
            if is_todo(r.get("own_name")) or is_todo(r.get("behavior", "x")):
                errs.append(f"catalog {r.get('id')}: own_name/behavior TODO")
        if d.get("candidates"):
            errs.append(f"candidates: осталось {len(d['candidates'])} — превратить в rules/catalog и удалить")
    return errs


def merge_by_system(recs: list[dict]) -> list[dict]:
    """Файлы с одинаковым system.id склеиваются: списки конкатенируются, goal — первый непустой."""
    by: dict[str, dict] = {}
    for r in recs:
        sid = r["system"]["id"]
        m = by.get(sid)
        if m is None:
            m = {"schema": r["schema"], "game": r["game"], "system": dict(r["system"]), "goal": "", "rules": [],
                 "catalog": [], "open_questions": [], "acceptance": [], "status": r.get("status", "draft"),
                 "_paths": []}
            by[sid] = m
        if not m["goal"] or is_todo(m["goal"]):
            m["goal"] = r.get("goal", "") or m["goal"]
        for k in ("rules", "catalog", "open_questions", "acceptance"):
            m[k] += r.get(k, []) or []
        if r.get("status", "draft") == "reviewed" and m["status"] != "reviewed":
            pass
        if r.get("status", "draft") != "skeleton":
            m["status"] = "draft" if m["status"] == "skeleton" else m["status"]
        m["_paths"].append(r.get("_path", ""))
        for b in r["system"].get("buckets", []) or []:
            m["system"].setdefault("buckets", [])
            if b not in m["system"]["buckets"]:
                m["system"]["buckets"].append(b)
    return [by[k] for k in sorted(by)]


def load_records(paths, validate: bool = True) -> list[dict]:
    recs = []
    for p in find_files(paths):
        d = load_file(p)
        if validate:
            errs = validate_schema(d)
            if errs:
                raise ValueError(f"{p}: схема:\n  " + "\n  ".join(errs))
        recs.append(d)
    return recs


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("paths", nargs="+")
    ap.add_argument("--strict", action="store_true")
    a = ap.parse_args()
    bad = 0
    for p in find_files(a.paths):
        d = load_file(p)
        errs = validate_schema(d) + validate_semantics(d, a.strict)
        print(("FAIL " if errs else "ok   ") + p.name + (f" ({len(errs)})" if errs else ""))
        for e in errs[:20]:
            print("   ", e)
        bad += bool(errs)
    sys.exit(1 if bad else 0)


if __name__ == "__main__":
    main()

