input.content:
"""records -> markdown в раскладке спеки WoL: Цель -> Поведение -> Числа -> Критерии приёмки -> Открытые вопросы.

  python render.py --records DIR_OR_FILE [...] --out DIR [--strip-sources] [--skip-skeleton]

Один md на систему (файлы с одним system.id склеиваются). Имя файла: system.spec_file или <id>-<slug>.md.
Раздел «Числа» содержит таблицу чисел правил и (подраздел «Каталог») строки каталога по видам.
`candidates` (рабочая зона скелета) не рендерится. Источники выводятся как «Источник: ...»
(как в спеке WoL); --strip-sources убирает их для публичной версии.
"""
from __future__ import annotations
import argparse, sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from recio import is_todo, load_records, merge_by_system  # noqa: E402

TODO_MARK = "**[TODO]**"


def fmt_val(v) -> str:
    if isinstance(v, dict):
        s = fmt_val(v.get("value"))
        if v.get("unit"):
            s += f" {v['unit']}"
        if v.get("note"):
            s += f" ({v['note']})"
        return s
    if isinstance(v, list):
        return " / ".join(fmt_val(x) for x in v)
    if isinstance(v, bool):
        return "да" if v else "нет"
    if isinstance(v, float) and v.is_integer() and abs(v) < 1e15:
        return f"{v:g}"
    return str(v)


def esc(s: str) -> str:
    return str(s).replace("|", "\\|").replace("\n", " ")


def txt(s) -> str:
    return TODO_MARK + " " + str(s).strip() if is_todo(s) else str(s).strip()


def render_system(m: dict, strip_sources: bool = False) -> tuple[str, dict]:
    sysd = m["system"]
    out = [f"# {sysd['id']} — {sysd['title']}", ""]
    st = {"rules": len(m["rules"]), "catalog": len(m["catalog"]), "todo": 0}

    out += ["## Цель", "", txt(m["goal"]) if m.get("goal") else TODO_MARK, ""]
    st["todo"] += is_todo(m.get("goal", ""))

    out += ["## Поведение", ""]
    if not m["rules"]:
        out += ["_Правил пока нет._", ""]
    for i, r in enumerate(m["rules"], 1):
        t = is_todo(r["behavior"])
        st["todo"] += t
        line = f"{i}. **{r['title'].rstrip('.')}.** {txt(r['behavior'])}"
        if r.get("conditions"):
            line += " Условия: " + "; ".join(r["conditions"]) + "."
        if r.get("numbers"):
            line += " Числа: " + ", ".join(f"{k} = {fmt_val(v)}" for k, v in r["numbers"].items()) + "."
        if r.get("source_refs") and not strip_sources:
            line += " *Источник: " + "; ".join(r["source_refs"]) + ".*"
        out.append(line)
    out.append("")

    out += ["## Числа", ""]
    rows = [(r, k, v) for r in m["rules"] for k, v in (r.get("numbers") or {}).items()]
    if rows:
        out += ["| Правило | Параметр | Значение |", "|---|---|---|"]
        out += [f"| {esc(r['id'] + ' ' + r['title'])} | {esc(k)} | {esc(fmt_val(v))} |" for r, k, v in rows]
        out.append("")
    elif not m["catalog"]:
        out += ["_Чисел пока нет._", ""]
    if m["catalog"]:
        out += ["### Каталог", ""]
        kinds: dict[str, list[dict]] = {}
        for r in m["catalog"]:
            kinds.setdefault(r["kind"], []).append(r)
        for kind, lst in kinds.items():
            out += [f"**{kind}** ({len(lst)})", "",
                    "| № | Название | Числа | Поведение" + ("" if strip_sources else " | Источник") + " |",
                    "|---|---|---|---" + ("" if strip_sources else "|---") + "|"]
            for r in lst:
                st["todo"] += is_todo(r.get("behavior", "")) or is_todo(r["own_name"])
                nums = "; ".join(f"{k} {fmt_val(v)}" for k, v in (r.get("numbers") or {}).items())
                row = f"| {esc(r['id'])} | {esc(txt(r['own_name']))} | {esc(nums)} | {esc(txt(r.get('behavior', '')))}"
                if not strip_sources:
                    row += f" | {esc(r.get('source_ref', ''))}"
                out.append(row + " |")
            out.append("")

    out += ["## Критерии приёмки", ""]
    out += [f"- [ ] {txt(a)}" for a in m["acceptance"]] or ["_Критериев пока нет._"]
    out += ["", "## Открытые вопросы", ""]
    out += [f"{i}. {txt(q)}" for i, q in enumerate(m["open_questions"], 1)] or ["_Открытых вопросов нет._"]
    return "\n".join(out).rstrip() + "\n", st


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--records", nargs="+", required=True)
    ap.add_argument("--out", required=True)
    ap.add_argument("--strip-sources", action="store_true")
    ap.add_argument("--skip-skeleton", action="store_true", help="не рендерить системы только со статусом skeleton")
    a = ap.parse_args()
    systems = merge_by_system(load_records(a.records))
    out = Path(a.out)
    out.mkdir(parents=True, exist_ok=True)
    total_todo = 0
    for m in systems:
        if a.skip_skeleton and m["status"] == "skeleton":
            print(f"[render] {m['system']['id']}: skeleton, пропуск")
            continue
        md, st = render_system(m, a.strip_sources)
        name = m["system"].get("spec_file") or f"{m['system']['id']}-{m['system']['slug']}.md"
        (out / name).write_text(md, encoding="utf-8")
        total_todo += st["todo"]
        print(f"[render] {name}: правил {st['rules']}, каталог {st['catalog']}, TODO {st['todo']}")
    if total_todo:
        print(f"[render] внимание: незаполненных TODO — {total_todo}")


if __name__ == "__main__":
    main()

