        for r in m["catalog"]:
            kinds.setdefault(r["kind"], []).append(r)
        for kind, lst in kinds.items():
            out += [f"**{kind}** ({len(lst)})", "",
                    "| № | Название | Числа | Поведение" + ("" if strip_sources else " | Источник") + " |",
                    "|---|---|---|---" + ("" if strip_sources else "|---") + "|"]
            for r in lst:
                st["todo"] += is_todo(r.get("behavior", "")) or is_todo(r["own_name"])
                nums = "; ".join(f"{k} {fmt_val(v)}" for k, v in (r.get("numbers") or {}).items())
                row = f"| {esc(r['id'])} | {esc(txt(r['own_name']))} | {esc(nums)} | {esc(txt(r.get('behavior', '')))}"
                if not strip_sources:
                    row += f" | {esc(r.get('source_ref', ''))}"
                out.append(row + " |")
            out.append("")

    out += ["## Критерии приёмки", ""]
    out += [f"- [ ] {txt(a)}" for a in m["acceptance"]] or ["_Критериев пока нет._"]
    out += ["", "## Открытые вопросы", ""]
    out += [f"{i}. {txt(q)}" for i, q in enumerate(m["open_questions"], 1)] or ["_Открытых вопросов нет._"]
    return "\n".join(out).rstrip() + "\n", st


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--records", nargs="+", required=True)
    ap.add_argument("--out", required=True)
    ap.add_argument("--strip-sources", action="store_true")
    ap.add_argument("--skip-skeleton", action="store_true", help="не рендерить системы только со статусом skeleton")
    a = ap.parse_args()
    systems = merge_by_system(load_records(a.records))
    out = Path(a.out)
    out.mkdir(parents=True, exist_ok=True)
    total_todo = 0
    for m in systems:
        if a.skip_skeleton and m["status"] == "skeleton":
            print(f"[render] {m['system']['id']}: skeleton, пропуск")
            continue
        md, st = render_system(m, a.strip_sources)
        name = m["system"].get("spec_file") or f"{m['system']['id']}-{m['system']['slug']}.md"
        (out / name).write_text(md, encoding="utf-8")
        total_todo += st["todo"]
        print(f"[render] {name}: правил {st['rules']}, каталог {st['catalog']}, TODO {st['todo']}")
    if total_todo:
        print(f"[render] внимание: незаполненных TODO — {total_todo}")


if __name__ == "__main__":
    main()

